import os, json
def msd(xs):
    n = len(xs); m = sum(xs)/n; v = sum((x-m)**2 for x in xs)/n
    return m, v**0.5
for ds, fz, pub_rr, pub_rrs in [
    ('Weather','last2', 0.255, 0.006),
    ('Weather','last4', 0.263, 0.017),
]:
    rrs = []
    for src in ('results/rr_moa','evidence_vm/rr_moa'):
        for seed in (42,43,44,45,46):
            p = os.path.join(src, f'{ds}_H96_K5_top2_{fz}_{seed}.json')
            if os.path.exists(p):
                d = json.load(open(p))
                rrs.append((seed, d['rr_moa']['mse'], src))
    # dedupe (results takes precedence)
    seen = {}
    for seed, v, src in rrs:
        if seed not in seen: seen[seed] = (v, src)
    print(f'{ds} {fz}: paper RR={pub_rr}±{pub_rrs}')
    for label, ss in [('42-44', (42,43,44)), ('42-45', (42,43,44,45)), ('42-46', (42,43,44,45,46))]:
        vals = [seen[s][0] for s in ss if s in seen]
        if len(vals) == len(ss):
            m, sd = msd(vals)
            tag = ' MATCH' if abs(m-pub_rr)<0.001 and abs(sd-pub_rrs)<0.0015 else ''
            print(f'  {label}: m={m:.4f}±{sd:.4f}{tag}')
